/* SQL ID : TeamGrpMgrDAO.teamGrpRegist 설명 : 팀 그룹 등록 */ INSERT INTO TB_LMS_TEAM_GRP ( TEAM_GRP_ID , SBJCT_ID , TEAM_GRPNM , TEAM_GRP_SEQNO , USEYN , DELYN , RGTR_ID , REG_DTTM , MDFR_ID , MOD_DTTM ) VALUES ( #{teamGrpId} , #{sbjctId} , #{teamGrpnm} , (SELECT NVL(MAX(TEAM_GRP_SEQNO), 0) + 1 FROM TB_LMS_TEAM_GRP WHERE SBJCT_ID = #{sbjctId}) , 'Y' , 'N' , #{rgtrId} , FN_DTTM() , #{mdfrId}
, FN_DTTM()
, null
)

/* SQL ID : TeamGrpMgrDAO.teamRegist 설명 : 팀 등록 */ INSERT INTO TB_LMS_TEAM ( TEAM_ID , TEAM_GRP_ID , TEAMNM , TEAM_QUOTA , TEAM_TYCD , AUTO_ALLOCYN , MRK_ACTV_TYCD , ACTV_GBNCD , TEAM_BBS_ID , TEAM_CPST_CMPTNYN , RGTR_ID , REG_DTTM , MDFR_ID , MOD_DTTM , TEAM_BBS_USEYN ) VALUES ( #{teamId} , #{teamGrpId} , #{teamnm} , #{teamQuota} , (SELECT CASE WHEN 1 <= #{teamTot} AND #{teamTot} <= 5 THEN 'SMALL' WHEN 6 <= #{teamTot} AND #{teamTot} <= 10 THEN 'MEDIUM' WHEN 11 <= #{teamTot} THEN 'LARGE' END FROM DUAL) , #{autoAllocyn} , #{mrkActvTycd} , 'ACTV' , #{teamBbsId} , 'Y' , #{rgtrId} , FN_DTTM() , #{mdfrId}
, FN_DTTM()
, null
, #{teamBbsUseyn} )

/*
    SQL ID : TeamGrpMgrDAO.teamMbrRegist
    설명 : 팀 멤버 등록
*/
INSERT INTO
    TB_LMS_TEAM_MBR
        ( TEAM_MBR_ID
        , TEAM_ID
        , USER_ID
        , ROLE
        , LDRYN
        , RGTR_ID
        , REG_DTTM
        , MDFR_ID
        , MOD_DTTM )
VALUES
        ( #{teamMbrId}
        , #{teamId}
        , #{userId}
        , #{role}
        , #{ldryn}
        , #{rgtrId}
        , FN_DTTM()
        , #{mdfrId}


        , FN_DTTM()


        , null


        )

mapper.update:
/*
    SQL ID : TeamGrpMgrDAO.updateTeamGrpInfo
    설명 : 팀 그룹 수정
*/
UPDATE
    TB_LMS_TEAM_GRP
SET
    TEAM_GRPNM   =   #{teamGrpnm}
    , MDFR_ID   =   #{mdfrId}
    , MOD_DTTM  =   FN_DTTM()
WHERE
    TEAM_GRP_ID = #{teamGrpId}

/*
    SQL ID : TeamGrpMgrDAO.updateTeamInfo
    설명 : 팀 수정
*/
UPDATE
    TB_LMS_TEAM
SET
    MDFR_ID             =   #{mdfrId}
    , MOD_DTTM          =   FN_DTTM()

    , TEAMNM            =   #{teamnm}


    , TEAM_QUOTA        =   #{teamQuota}


    , TEAM_TYCD         =   (SELECT
                                CASE
                           WHEN 1 <= #{teamTot} AND #{teamTot} <= 5 THEN 'SMALL'   
                           WHEN 6 <= #{teamTot} AND #{teamTot} <= 10 THEN 'MEDIUM' 
                           WHEN 11 <= #{teamTot} THEN 'LARGE'                      
                                END
                            FROM
                                DUAL)


    , AUTO_ALLOCYN      =   #{autoAllocyn}


    , MRK_ACTV_TYCD     =   #{mrkActvTycd}


    , ACTV_GBNCD        =   #{actvGbncd}


    , TEAM_BBS_ID       =   #{teamBbsId}


    , TEAM_CPST_CMPTNYN =   #{teamCpstCmptnyn}


    , TEAM_BBS_USEYN    =   #{teamBbsUseyn}

WHERE
    TEAM_ID = #{teamId}
